// SystemVerilog 8-bit Pipelined ALU with Forwarding
module risc_alu (
    input  logic [7:0] a, b,
    input  logic [2:0] opcode,
    output logic [7:0] alu_out,
    output logic       zero_flag
);
    always_comb begin
        case (opcode)
            3'b000: alu_out = a + b;         // ADD
            3'b001: alu_out = a - b;         // SUB
            3'b010: alu_out = a & b;         // AND
            3'b011: alu_out = a | b;         // OR
            3'b100: alu_out = a ^ b;         // XOR
            3'b101: alu_out = a << b[2:0];   // SLL
            3'b110: alu_out = a >> b[2:0];   // SRL
            default: alu_out = 8'h00;
        endcase
    end
    assign zero_flag = (alu_out == 8'h00);
endmodule

// Dual-FF Synchronizer for CDC control
module cdc_2ff_sync (
    input  logic dest_clk,
    input  logic dest_rst_n,
    input  logic async_in,
    output logic sync_out
);
    (* ASYNC_REG = "TRUE" *) logic sync_ff1, sync_ff2;
    always_ff @(posedge dest_clk or negedge dest_rst_n) begin
        if (!dest_rst_n) begin
            sync_ff1 <= 1'b0;
            sync_ff2 <= 1'b0;
        end else begin
            sync_ff1 <= async_in;
            sync_ff2 <= sync_ff1;
        end
    end
    assign sync_out = sync_ff2;
endmodule

#include "stm32g4xx.h"
#include "arm_math.h"

#define BUFFER_SIZE 1024
#define FFT_SIZE    512

ALIGN_32BYTES(uint16_t adc_dma_buffer[BUFFER_SIZE]);
float32_t fft_input[FFT_SIZE];
float32_t fft_output[FFT_SIZE];
arm_rfft_fast_instance_f32 S_fft;

void DMA1_Channel1_IRQHandler(void) {
    if (DMA1->ISR & DMA_ISR_HTIF1) {
        DMA1->IFCR = DMA_IFCR_CHTIF1; // Clear Half-Transfer Flag
        for (int i = 0; i < FFT_SIZE; i++) {
            fft_input[i] = (float32_t)adc_dma_buffer[i] * (3.3f / 4095.0f);
        }
        arm_rfft_fast_f32(&S_fft, fft_input, fft_output, 0);
    }
    if (DMA1->ISR & DMA_ISR_TCIF1) {
        DMA1->IFCR = DMA_IFCR_CTCIF1; // Clear Transfer-Complete Flag
        for (int i = 0; i < FFT_SIZE; i++) {
            fft_input[i] = (float32_t)adc_dma_buffer[FFT_SIZE + i] * (3.3f / 4095.0f);
        }
        arm_rfft_fast_f32(&S_fft, fft_input, fft_output, 0);
    }
}

#include "FreeRTOS.h"
#include "task.h"
#include "semphr.h"
#include "queue.h"

SemaphoreHandle_t xI2CMutex;
QueueHandle_t     xSensorQueue;

typedef struct {
    float ax, ay, az;
    uint32_t timestamp;
} ImuData_t;

void vImuTask(void *pvParameters) {
    TickType_t xLastWakeTime = xTaskGetTickCount();
    const TickType_t xFrequency = pdMS_TO_TICKS(10); // Exact 100Hz Loop
    ImuData_t rawData;

    for (;;) {
        vTaskDelayUntil(&xLastWakeTime, xFrequency);

        // Acquire I2C Bus Mutex with Priority Inheritance
        if (xSemaphoreTake(xI2CMutex, pdMS_TO_TICKS(5)) == pdTRUE) {
            // Read IMU registers via I2C
            rawData.ax = 0.01f; rawData.ay = 0.02f; rawData.az = 0.98f;
            rawData.timestamp = xTaskGetTickCount();
            xSemaphoreGive(xI2CMutex);

            // Zero-copy pointer enqueue
            ImuData_t *pData = &rawData;
            xQueueSend(xSensorQueue, &pData, 0);
        }
    }
}

// FreeRTOS Stack Overflow Hook for reliability signoff
void vApplicationStackOverflowHook(TaskHandle_t xTask, char *pcTaskName) {
    // Halt CPU immediately upon stack breach
    __disable_irq();
    while (1);
}

#include "stm32g4xx.h"

// I2C Bus Hang-up 9-Clock Recovery Sequence
void I2C_Force_Bus_Recovery(GPIO_TypeDef *scl_port, uint16_t scl_pin, GPIO_TypeDef *sda_port, uint16_t sda_pin) {
    // Configure SCL and SDA as Open-Drain Output
    // 1. Check if SDA is held LOW by a stuck slave
    if ((sda_port->IDR & sda_pin) == 0) {
        // 2. Clock SCL up to 9 times to release slave
        for (int i = 0; i < 9; i++) {
            scl_port->BSRR = scl_pin;        // SCL High
            for (volatile int d = 0; d < 100; d++);
            scl_port->BRR  = scl_pin;        // SCL Low
            for (volatile int d = 0; d < 100; d++);
            if (sda_port->IDR & sda_pin) {
                break; // Slave released SDA!
            }
        }
        // 3. Generate STOP condition: SDA Low -> High while SCL is High
        sda_port->BRR  = sda_pin; // SDA Low
        scl_port->BSRR = scl_pin; // SCL High
        for (volatile int d = 0; d < 100; d++);
        sda_port->BSRR = sda_pin; // SDA High (STOP)
    }
}

// C-code for Inverter dq-Axis Current Controller with Decoupling
typedef struct {
    float id_ref, iq_ref;
    float id_fb,  iq_fb;
    float vd_grid, vq_grid;
    float kp, ki;
    float integ_d, integ_q;
    float omega_L;
} DQ_Controller_t;

void Run_Current_Loop(DQ_Controller_t *ctrl, float *vd_cmd, float *vq_cmd, float dt) {
    // 1. Calculate Error
    float err_d = ctrl->id_ref - ctrl->id_fb;
    float err_q = ctrl->iq_ref - ctrl->iq_fb;

    // 2. PI Integrator
    ctrl->integ_d += ctrl->ki * err_d * dt;
    ctrl->integ_q += ctrl->ki * err_q * dt;

    // 3. PI Output + Cross-Coupling Decoupling + Grid Voltage Feedforward
    // Vd = -(PI_d) + omega*L*iq + Vd_grid
    // Vq = -(PI_q) - omega*L*id + Vq_grid
    *vd_cmd = -(ctrl->kp * err_d + ctrl->integ_d) + (ctrl->omega_L * ctrl->iq_fb) + ctrl->vd_grid;
    *vq_cmd = -(ctrl->kp * err_q + ctrl->integ_q) - (ctrl->omega_L * ctrl->id_fb) + ctrl->vq_grid;
}
